"""
Held — build the web heart model from the printed chunks.

Imports the latest version (_vNN) of every chunk STL, joins them (they are already in assembled
print coordinates, millimetres, Z up, front = -Y), merges seam vertices, centres the bounding box
on the origin, decimates for the web and exports a Draco-compressed GLB. glTF is Y up, so in the
simulator's frame (x right, y up, z toward the viewer) the heart's front faces the viewer.

The GLB is also wrapped as a script (window.HeldHeartModel = {glb: <base64>}) because a <script>
tag can be loaded cross-origin without CORS headers, so the controller's own page can use the
copy hosted on istariarts.org.

  blender -b --factory-startup --python tools/held/heart/build_heart.py -- <stl dir> <out.js> [ratio]
"""
import base64, bpy, glob, json, os, re, sys, tempfile

args = sys.argv[sys.argv.index("--") + 1:]
src, out_js = args[0], args[1]
ratio = float(args[2]) if len(args) > 2 else 0.2

# newest version of each chunk name
latest = {}
for f in glob.glob(os.path.join(src, "*.stl")):
    m = re.match(r"(.+?)_RC_v(\d+)\.stl$", os.path.basename(f))
    if not m:
        continue
    name, ver = m.group(1), int(m.group(2))
    if name not in latest or ver > latest[name][0]:
        latest[name] = (ver, f)

bpy.ops.wm.read_factory_settings(use_empty=True)
objs = []
for name in sorted(latest):
    bpy.ops.wm.stl_import(filepath=latest[name][1])
    o = bpy.context.selected_objects[0]
    o.name = name
    objs.append(o)
    print("HEART using %s v%02d" % (name, latest[name][0]))

bpy.ops.object.select_all(action="DESELECT")
for o in objs:
    o.select_set(True)
bpy.context.view_layer.objects.active = objs[0]
bpy.ops.object.join()
heart = bpy.context.active_object
heart.name = "Heart"

bpy.ops.object.mode_set(mode="EDIT")
bpy.ops.mesh.select_all(action="SELECT")
bpy.ops.mesh.remove_doubles(threshold=0.05)
bpy.ops.mesh.normals_make_consistent(inside=False)
bpy.ops.object.mode_set(mode="OBJECT")
before = len(heart.data.polygons)

mod = heart.modifiers.new("Decimate", "DECIMATE")
mod.ratio = ratio
bpy.ops.object.modifier_apply(modifier=mod.name)
bpy.ops.object.shade_smooth()

def bounds():
    vs = [v.co for v in heart.data.vertices]
    return [min(v[i] for v in vs) for i in range(3)], [max(v[i] for v in vs) for i in range(3)]

mn, mx = bounds()
centre = [(a + b) / 2 for a, b in zip(mn, mx)]
for v in heart.data.vertices:
    v.co.x -= centre[0]; v.co.y -= centre[1]; v.co.z -= centre[2]
mn, mx = bounds()
print("HEART tris %d -> %d" % (before, len(heart.data.polygons)))
print("HEART print-space centre (%.1f %.1f %.1f) moved to origin" % tuple(centre))
print("HEART half extents x=%.1f (width) y=%.1f (depth) z=%.1f (height)" % tuple((b - a) / 2 for a, b in zip(mn, mx)))

glb = os.path.join(tempfile.mkdtemp(), "heart.glb")
bpy.ops.export_scene.gltf(filepath=glb, export_format="GLB", use_selection=True, export_apply=True,
    export_texcoords=False, export_materials="NONE", export_yup=True,
    export_draco_mesh_compression_enable=True, export_draco_mesh_compression_level=10,
    export_draco_position_quantization=14, export_draco_normal_quantization=10)
with open(glb, "rb") as f:
    data = f.read()
with open(out_js, "w", newline="\n") as f:
    f.write("// Held heart model (Draco GLB, millimetres, Y up, front toward +Z). Generated by\n")
    f.write("// HeldController tools/held/heart/build_heart.py from the printed chunk STLs; do not edit.\n")
    f.write("window.HeldHeartModel = %s;\n" % json.dumps({
        "chunks": sorted(latest), "tris": len(heart.data.polygons),
        "printCentre": [round(c, 1) for c in centre], "glb": base64.b64encode(data).decode("ascii")}))
print("HEART wrote %s (glb %d bytes, js %d bytes)" % (out_js, len(data), os.path.getsize(out_js)))
# AI: end
